run:
(root) => {
    const el = root.querySelector('.tw');
    if (!el) return;
    const words = ['designers', 'founders', 'creators', 'everyone'];
    let w = 0;
    let i = 0;
    let del = false;
    const step = () => {
      if (!root.isConnected) return;
      if (root.dataset.paused) {
        setTimeout(step, 300);
        return;
      }
      const word = words[w];
      if (!del) {
        i++;
        el.textContent = word.slice(0, i);
        if (i === word.length) {
          del = true;
          setTimeout(step, 1300);
          return;
        }
        setTimeout(step, 85);
      } else {
        i--;
        el.textContent = word.slice(0, i);
        if (i === 0) {
          del = false;
          w = (w + 1) % words.length;
          setTimeout(step, 380);
          return;
        }
        setTimeout(step, 42);
      }
    };
    setTimeout(step, 500);
  }

