run:
(root) => {
    const shots = [...root.querySelectorAll('.sh')];
    let k = 0;
    const tick = () => {
      if (!root.isConnected) return;
      if (!root.dataset.paused) {
        k = (k + 1) % shots.length;
        shots.forEach((s, i) => (s.dataset.p = String((i + shots.length - k) % shots.length)));
      }
      setTimeout(tick, 2100);
    };
    setTimeout(tick, 1500);
  }

